/* =====================================================================================
   TASKS - a to-do list + habit tracker. p0pc0rn skeleton "list-tasks" (p0pc0rn Kit v1.3).
   Serves: Productivity (to-dos, reminders, checklists), Lifestyle (errands, routines),
           Health & Fitness (daily habits, streaks, counters like glasses of water).

   SCREENS (bottom tab bar: Tasks / Habits / Settings)
     Tasks    - large title that collapses on scroll, a progress-ring card for today, then
                TODAY / UPCOMING / DONE sections. Tap a circle to complete a task (the disc
                springs full, a strike draws across, then the row slides down to Done).
                Swipe a row left for Delete (with Undo). Tap a row to edit it. + adds one.
     Habits   - a 7-day strip of completion rings, habit cards with streaks (tap to log,
                hold to reset) and a "This week" bar chart.
     Settings - profile card, toggles, a segmented sort order, clear / reset (inline confirm).
     Sheet    - "New Task" / "Edit Task": text field, suggestions, due date, priority pills.
   STATES: loading skeleton (first second), empty section (K.empty), form error (wiggle +
   red text), win (all of today done -> confetti + toast), undo bar after a delete.

   TO MAKE A NEW APP FROM THIS FILE
     - REPLACE the sample data block (lists, tasks, habits, suggestions, profile, empty copy)
       and ACCENT / SKY. Keep the machinery below it.
     - layoutTasks() decides the sections; drawRowCard() decides what a row shows;
       drawSheetBody() decides the form. A grocery, reading or packing list only changes those.
     - Keep: springs toward layout targets (every change animates by itself), rowSwipe()
       (swipe-to-reveal), persist() after every change. An open K.sheet is modal by itself
       (nothing under it takes taps) and K.clip keeps scrolled rows from stealing the bars' taps.
   ===================================================================================== */

// ===== THEME + LAYOUT CONSTANTS =====
const ACCENT = (window.SLOTS && window.SLOTS.accent) || '#2f6bff';          // REPLACE: brand blue (a saturated mid blue reads well on light grey)
const SKY = '#5ac8fa';             // second hue: ring gradients, sparks
const SIDE = 16;                   // screen margin: every card sits 16 px in from each edge
const SUMMARY_H = 116, HEAD_H = 40, ROW_H = 64, ROW_GAP = 8, EMPTY_H = 172;   // EMPTY_H: empty card until K.empty reports its height
const ACTION_W = 84;               // width of the red Delete action a left swipe reveals
const SHEET_H = 456;
const WEEK_H = 96, HABIT_H = 76, HABIT_GAP = 10, CHART_H = 190;
const SETTINGS_H = 690;            // profile 88 + general 256 + order 110 + data 160 + footer and padding 76
const LOAD_S = 0.6;                // LOADING: seconds of skeleton rows at launch (a synced app waits for its fetch here)
const UNDO_S = 5;                  // how long the Undo bar stays after a delete
const DAY_MS = 86400000;

// ===== SAMPLE DATA (REPLACE for a new app) =====
const SL = window.SLOTS || {};
// REPLACE: list names and their colours (the dot in front of each row's due date).
const DEF_LISTS = { Inbox: '#8e8e93' };
const PRIO_NAMES = ['None', 'Low', 'Medium', 'High'];
const PRIO_MARKS = ['', '!', '!!', '!!!'];          // Reminders-style priority marks at the right of a row
const DUE_CHOICES = [{ label: 'Today', days: 0 }, { label: 'Tomorrow', days: 1 }, { label: 'Next week', days: 7 }];
// REPLACE: starter tasks. due = days from today (negative = overdue). doneHoursAgo = already finished.
const DEF_TASKS = [];
// REPLACE: starter habits. goal > 1 makes a counter. week = the 6 days before today (1 = kept).
const DEF_HABITS = [];
const DEF_SUGGESTIONS = ['Groceries', 'Call back', 'Tidy up'];      // REPLACE: one-tap titles in the add sheet
const DEF_PROFILE = { name: 'Me', plan: 'Personal' };            // REPLACE
const REMIND_TIMES = ['7:00 AM', '8:00 AM', '9:00 AM', '6:00 PM', '9:00 PM'];
const SECTION_TITLES = { today: 'TODAY', upcoming: 'UPCOMING', done: 'DONE' };
const EMPTY_COPY = {                                                    // REPLACE: icon, headline, one line of guidance
  today: ['sparkle', 'All clear for today', 'Nothing left due. Enjoy the quiet or pull a task forward.'],
  upcoming: ['calendar', 'Nothing scheduled', 'Tasks due tomorrow or later collect here.'],
  done: ['check', 'Nothing done yet', 'Tick a circle and the task lands here.']
};
const okIcon = (n, d) => (typeof n === 'string' && (!K.ICONS || K.ICONS.includes(n)) ? n : d);
// ----- slots (window.SLOTS from slots.js; missing -> the sample above) -----
const LISTS = Array.isArray(SL.lists) && SL.lists.length ? Object.fromEntries(SL.lists.slice(0, 8).map((l) => [String(l.name || 'List').slice(0, 18), l.color || '#8e8e93'])) : DEF_LISTS;
const SAMPLE_TASKS = Array.isArray(SL.tasks) ? SL.tasks.slice(0, 30).map((t) => Object.assign({ title: String(t.title || 'Task').slice(0, 60),
  list: LISTS[t.list] ? t.list : Object.keys(LISTS)[0], due: Number.isFinite(+t.due) ? Math.round(+t.due) : 0, prio: Math.max(0, Math.min(3, Math.round(+t.prio || 0))) },
  t.doneHoursAgo != null ? { doneHoursAgo: +t.doneHoursAgo } : {})) : DEF_TASKS;
const SAMPLE_HABITS = Array.isArray(SL.habits) ? SL.habits.slice(0, 8).map((h) => ({ name: String(h.name || 'Habit').slice(0, 30), icon: okIcon(h.icon, 'check'),
  color: h.color || '#34c759', goal: Math.max(1, Math.round(+h.goal || 1)), unit: String(h.unit || ''), count: 0, streak: 0, week: [0, 0, 0, 0, 0, 0] })) : DEF_HABITS;
const SUGGESTIONS = Array.isArray(SL.suggestions) && SL.suggestions.length ? SL.suggestions.slice(0, 3).map((x) => String(x).slice(0, 28)) : DEF_SUGGESTIONS;
const PROFILE = SL.profile_name ? { name: String(SL.profile_name).slice(0, 30), plan: 'Personal' } : DEF_PROFILE;
const TITLE_MAIN = String(SL.title || 'Tasks').slice(0, 22), TITLE_HABITS = String(SL.habits_title || 'Habits').slice(0, 22);
const TABS = [{ icon: 'list', label: TITLE_MAIN, scene: 'tasks' }, { icon: 'flame', label: TITLE_HABITS, scene: 'habits' },
  { icon: 'settings', label: 'Settings', scene: 'settings' }];

// ===== STATE + PERSISTENCE =====
let tasks = [], habits = [], prefs = {}, nextId = 1;
// Runtime-only UI state. Never saved: it holds K.t times and springs that mean nothing after a reload.
const ui = { tab: 0, undo: null, resetArmedUntil: 0, ringPos: { x: 0, y: 0 },
  sheet: { open: false, mode: 'add', editId: null, draft: null, error: false, errorAt: -9 } };
const rowUI = {};      // task id -> { spr, pid, grab, open, leaving, fade }: swipe + delete motion
const settleAt = {};   // task id -> K.t when a just-ticked task may slide down to Done
const bornAt = {};     // task id -> K.t when its row appeared (pop-in for new / restored rows)
const emptyHt = {};    // section -> height of its empty card, from what K.empty returned last frame

function loadAll() {
  const savedTasks = K.load('tasks.v1', null), savedHabits = K.load('habits.v1', null);
  tasks = Array.isArray(savedTasks) ? savedTasks : buildSampleTasks();
  habits = Array.isArray(savedHabits) ? savedHabits : buildSampleHabits();
  prefs = Object.assign({ sound: true, reminder: true, remindAt: 1, showDone: true, sort: 0 }, K.load('prefs.v1', {}));
  ui.tab = Math.max(0, Math.min(TABS.length - 1, K.load('tab', 0) | 0));
  nextId = tasks.reduce((m, t) => Math.max(m, t.id), 0) + 1;
  K.sound = prefs.sound;
  rolloverHabits();                  // a new day since the last visit closes out yesterday's habits
  persist();
}
function persist() { K.save('tasks.v1', tasks); K.save('habits.v1', habits); K.save('prefs.v1', prefs); }

function buildSampleTasks() {
  const today = todayNum();
  return SAMPLE_TASKS.map((s, i) => ({ id: i + 1, title: s.title, list: s.list, due: today + s.due, prio: s.prio,
    done: s.doneHoursAgo != null, doneAt: s.doneHoursAgo != null ? Date.now() - s.doneHoursAgo * 3600000 : 0 }));
}
function buildSampleHabits() {
  return SAMPLE_HABITS.map((s, i) => Object.assign({ id: i + 1, unit: '', day: todayNum() }, s, { week: s.week.slice() }));
}
function resetAll() {
  tasks = buildSampleTasks(); habits = buildSampleHabits(); nextId = tasks.length + 1;
  for (const id in rowUI) delete rowUI[id];
  for (const id in settleAt) delete settleAt[id];
  tasks.forEach((t, i) => { bornAt[t.id] = K.t + i * 0.05; });   // rows pop back in one after another
  ui.undo = null; ui.resetArmedUntil = 0;
  persist(); K.sfx('whoosh');
  K.toast('Sample data restored', { tone: 'good', icon: 'refresh' });
}
function clearCompleted(n) {
  if (!n) { K.sfx('error'); K.toast('Nothing to clear yet', { tone: 'warn' }); return; }
  tasks = tasks.filter(t => !t.done); persist(); K.sfx('whoosh');
  K.toast('Cleared ' + n + ' completed ' + (n === 1 ? 'task' : 'tasks'), { tone: 'good', icon: 'trash' });
}

// ===== DATES + TASK QUERIES =====
// A local calendar day number (days since 1970 in the phone's time zone): due dates compare as integers.
function dayNumber(ts) { return Math.floor((ts - new Date(ts).getTimezoneOffset() * 60000) / DAY_MS); }
function todayNum() { return dayNumber(Date.now()); }
function dueLabel(t) {
  const d = t.due - todayNum();
  if (d === 0) return 'Today';
  if (d === 1) return 'Tomorrow';
  if (d === -1) return 'Yesterday';
  if (d < 0) return -d + ' days overdue';
  return K.fmt.date(Date.now() + d * DAY_MS);            // 'Wed, Sep 30'
}
function dueIndex(due) { const d = due - todayNum(); return d <= 0 ? 0 : d === 1 ? 1 : 2; }
function prioColor(p) { return ['#8e8e93', ACCENT, K.C.warn, K.C.bad][p] || '#8e8e93'; }

// WHY settleAt: a fresh tick stays in place ~0.75 s so the strike can draw on before the row moves.
function sectionOf(t) {
  if (t.done && !(settleAt[t.id] > K.t)) return 'done';
  return t.due <= todayNum() ? 'today' : 'upcoming';
}
function sectionTasks(sec) {
  const rows = tasks.filter(t => sectionOf(t) === sec);
  if (sec === 'done') return rows.sort((a, b) => b.doneAt - a.doneAt);
  const byDue = (a, b) => a.due - b.due || b.prio - a.prio || a.id - b.id;
  const byPrio = (a, b) => b.prio - a.prio || a.due - b.due || a.id - b.id;
  return rows.sort(prefs.sort === 1 ? byPrio : byDue);
}
function todayStats() {
  const today = todayNum();
  const openList = tasks.filter(t => !t.done && t.due <= today);
  const done = tasks.filter(t => t.done && dayNumber(t.doneAt) === today).length;
  const total = openList.length + done;
  return { open: openList.length, done, total, overdue: openList.filter(t => t.due < today).length, ratio: total ? done / total : 1 };
}

// ===== SETUP + FRAME =====
function setup() {
  K.setup({ mode: 'light', accent: ACCENT });
  loadAll();
  K.scene('tasks', drawTasks);                         // the first scene registered opens first
  K.scene('habits', drawHabits);
  K.scene('settings', drawSettings);
  if (ui.tab) K.go(TABS[ui.tab].scene, 'none');        // reopen on the tab the user left
}

function draw() {
  K.render();                                          // current screen (+ transition), particles, rings
  drawUndoBar();
  drawTabBar();
  drawTaskSheet();                                     // LAST: an open K.sheet is modal, so nothing drawn before it takes taps
}

function drawTabBar() {
  const i = K.tabBar('tabs', TABS, ui.tab);
  if (i === ui.tab) return;
  ui.tab = i; K.save('tab', i); closeAllRows();
  K.go(TABS[i].scene, 'fade', 240);
}

// ===== SHARED UI HELPERS =====
function tabBarH() { return 58 + K.safe.bottom; }
function viewBottom() { return K.H - tabBarH(); }
function barBottom() { return K.navBar.barH || K.safe.top + 50; }
// Screen content lives between the nav bar and the tab bar, so rows vanish cleanly under the collapsed title.
// K.clip also limits every kit hit test inside it (K.tapIn, K.holdIn, list rows, toggles) to that band:
// a row scrolled under a bar can never steal the bar's taps.
function contentClip(fn) { K.clip(0, barBottom(), K.W, viewBottom() - barBottom(), fn); }
// Where scrolled content may take taps: below the nav bar, above the tab bar, and above the Undo bar while it shows.
function hitBottom() { return viewBottom() - (ui.undo ? 76 : 0); }
// KIT GAP (v1.1): the Undo bar is a NON-modal overlay drawn after the screen, and the first K.tapIn wins, so a row
// under it would take its taps. Rows run their hit tests (never their drawing) inside a clip that stops above it.
function aboveUndo(fn) { K.clip(0, 0, K.W, hitBottom(), fn); }
// KIT GAP (v1.1): the tester's controls map ignores K.clip, and the tester taps the CENTRE of each listed rect. A custom
// hit area lists only its visible part of the band (16 px or more), so a listed centre never sits under a bar.
function mapVisible(name, x, y, w, h) {
  const y0 = Math.max(y, barBottom()), y1 = Math.min(y + h, hitBottom());
  if (y1 - y0 >= 16) K.registerControl(name, x, y0, w, y1 - y0);
}
// Kit controls list their FULL rect, so one in scrolled content is live only while its centre is between the bars and it
// is clear of the Undo bar; otherwise K.inert leaves it out of the map (its visible part is still clipped by K.clip).
function liveInBand(y, h, fn) {
  const c = y + h / 2, underUndo = !!ui.undo && y + h > hitBottom();
  return K.inert(c < barBottom() || c > viewBottom() || underUndo, fn);
}
// Fades a group of DRAWING through the public K.with hook (K.progressRing, K.avatar, K.empty, K.bars take no alpha).
// Kit CONTROLS take { alpha } instead (below 0.3 they are also inert): the Settings groups show that.
function faded(a, fn) { K.with(ctx => { ctx.globalAlpha *= K.clamp(a, 0, 1); fn(); }); }
// Tasks entrance: K.stagger times from when this screen opened; on first launch the list also waits for the
// loading skeleton (K.since from LOAD_S, the K.t at which the real list first appears).
function listIn(i) { return Math.min(K.stagger(i, 45, 420), K.since(LOAD_S, i * 45, 420)); }
function rise(e) { return 14 * (1 - e); }

function screenBackdrop() {
  K.backdrop({ top: '#f8f9fc', bottom: K.C.bg, vignette: 0, grain: 0.025, glow: [
    { x: K.W * 0.9, y: K.safe.top + 30, r: 320, color: ACCENT, s: 0.09 }, { x: 0, y: K.H * 0.72, r: 280, color: SKY, s: 0.07 }] });
}
function sectionHeader(title, right, y, a) {
  K.text(title, SIDE + 4, y + 28, 'label', K.C.text2, { alpha: a });
  if (right) K.text(right, K.W - SIDE - 4, y + 28, 'footnote', K.C.text3, { align: 'right', alpha: a });
}

// A selectable pill (priority, suggestions, filters): draws, registers for the tester, returns {w, tap}.
function pillWidth(label) { return K.measure(label, 'subhead', { weight: 600 }) + 26; }
function choicePill(id, x, y, label, on, col) {
  const w = pillWidth(label), h = 34;
  const k = K.clamp(K.springTo('pill:' + id, on ? 1 : 0, { k: 400, d: 26 }), 0, 1);
  K.registerControl(id, x, y - 5, w, h + 10);
  K.uiRect(x, y, w, h);
  const tap = !!K.tapIn(x, y - 5, w, h + 10);
  K.rect(x, y, w, h, { r: h / 2, fill: K.mix(K.alpha(col, 0.12), col, k), elev: on ? 1 : 0 });
  K.text(label, x + w / 2, y + h / 2 + 0.5, 'subhead', K.mix(col, '#ffffff', k), { align: 'center', base: 'middle', weight: 600 });
  return { w, tap };
}

// ===== TASKS SCREEN =====
function drawTasks() {
  screenBackdrop();
  const lay = layoutTasks();
  const sub = K.fmt.date(Date.now(), { weekday: 'long', month: 'long', day: 'numeric' }), top = K.navBar.top(sub);
  const off = K.scroll('tasks', 0, 0, K.W, viewBottom(), top + lay.height + 24);
  const y0 = top - off;
  contentClip(() => {
    if (K.t < LOAD_S) { drawLoadingState(y0); return; }
    const e = listIn(0);
    faded(e, () => drawSummaryCard(SIDE, y0 + rise(e), K.W - SIDE * 2));
    drawTaskItems(lay.items, y0);
  });
  if (K.navBar(TITLE_MAIN, off, { right: { id: 'add', icon: 'plus' }, sub }) === 'add') openSheet('add', null);
  if (K.freeTap()) closeAllRows();                     // a tap on empty space closes an open swipe
}

// Where every header, row and empty card SHOULD be (y from the top of the content). drawTaskItems()
// springs each block toward its target, so ticking, deleting, adding and re-sorting all animate by themselves.
function layoutTasks() {
  const items = [];
  let y = SUMMARY_H + 8;
  for (const sec of ['today', 'upcoming', 'done']) {
    if (sec === 'done' && !prefs.showDone) continue;
    const rows = sectionTasks(sec);
    items.push({ key: 'h:' + sec, kind: 'header', y, sec, count: rows.length });
    y += HEAD_H;
    if (!rows.length) { items.push({ key: 'e:' + sec, kind: 'empty', y, sec }); y += emptyH(sec) + ROW_GAP; }
    else K.anim('empty:' + sec, 0, 1000);             // re-arm the empty card's fade-in for next time
    for (const t of rows) { items.push({ key: 't:' + t.id, kind: 'task', y, task: t }); y += ROW_H + ROW_GAP; }
  }
  return { items, height: y };
}

function drawTaskItems(items, y0) {
  const flying = [];
  items.forEach((it, i) => {
    const sy = K.springTo('y:' + it.key, it.y, { k: 190, d: 22 });
    const e = listIn(i + 1);
    const lift = K.clamp(Math.abs(sy - it.y) / 30, 0, 1);   // 0 at rest, 1 while sliding between sections
    const job = () => faded(e, () => drawTaskItem(it, y0 + sy + rise(e), lift));
    if (lift > 0.1) flying.push(job); else job();
  });
  flying.forEach(job => job());                        // rows in flight draw last so they pass OVER the rest
}

function drawTaskItem(it, y, lift) {
  if (it.kind === 'empty') { drawEmptySection(it.sec, y); return; }   // no controls; always drawn so it keeps its measure
  // Outside the band between the bars: nothing to draw, tap or offer the tester (partly hidden rows: mapVisible).
  if (y > viewBottom() || y + (it.kind === 'task' ? ROW_H : HEAD_H) < barBottom()) return;
  if (it.kind === 'header') sectionHeader(SECTION_TITLES[it.sec], it.count ? String(it.count) : '', y);
  else drawTaskRow(it.task, SIDE, y, K.W - SIDE * 2, lift);
}

function drawSummaryCard(x, y, w) {
  const s = todayStats(), allDone = s.open === 0;
  K.card(x, y, w, SUMMARY_H, { r: 20 });
  const cx = x + 58, cy = y + SUMMARY_H / 2;
  ui.ringPos = { x: cx, y: cy };
  if (allDone) K.glow(cx, cy, 66, K.C.good, 0.14 + 0.1 * K.pulse(2.5));
  K.progressRing(cx, cy, 36, K.anim('ring', s.ratio, 5), { width: 10, color: allDone ? [K.C.good, '#63e6be'] : [ACCENT, SKY] });
  K.num(Math.round(K.count('pct', Math.round(s.ratio * 100), 700)) + '%', cx, cy + 6, 'headline', K.C.text, { align: 'center' });
  const tx = x + 116, maxW = w - 132;
  const title = s.total === 0 ? 'Nothing due today' : allDone ? 'All done today' : s.done + ' of ' + s.total + ' done';
  K.text("TODAY'S PROGRESS", tx, y + 34, 'label', K.C.text3);
  K.text(title, tx, y + 62, 'title2', K.C.text, { maxW });
  if (allDone) { K.chip(tx, y + 76, s.done ? s.done + ' completed' : 'Free day', { color: K.C.good, icon: 'check' }); return; }
  const cw = K.chip(tx, y + 76, s.open + ' left', { color: ACCENT, icon: 'clock' });
  if (s.overdue) K.chip(tx + cw + 8, y + 76, s.overdue + ' overdue', { color: K.C.bad, icon: 'alert' });
}

// LOADING state: skeletons shaped like the real card and rows, with a moving shimmer, while data restores.
function drawLoadingState(y) {
  K.card(SIDE, y, K.W - SIDE * 2, SUMMARY_H, { r: 20 });
  K.shimmer(SIDE + 17, y + 17, 82, 82, 41);
  K.shimmer(SIDE + 116, y + 26, 120, 10, 5);
  K.shimmer(SIDE + 116, y + 44, 170, 20, 10);
  K.shimmer(SIDE + 116, y + 76, 76, 24, 12);
  y += SUMMARY_H + 8;
  K.shimmer(SIDE + 4, y + 18, 64, 10, 5);
  const rows = Math.ceil((viewBottom() - y - HEAD_H) / (ROW_H + ROW_GAP));   // fill the view: no blank half-screen
  for (let i = 0; i < rows; i++) {
    const ry = y + HEAD_H + i * (ROW_H + ROW_GAP);
    K.card(SIDE, ry, K.W - SIDE * 2, ROW_H, { r: 16, elev: 1 });
    K.shimmer(SIDE + 18, ry + 20, 24, 24, 12);
    K.shimmer(SIDE + 56, ry + 17, 180 - (i % 4) * 22, 13, 6);
    K.shimmer(SIDE + 56, ry + 39, 96, 10, 5);
  }
}

// EMPTY state for one section: a card around the kit's empty-state block, fading in the moment it empties.
// K.empty returns the height it used (1 or 2 body lines); the card is drawn first, so it uses last frame's answer.
function emptyH(sec) { return emptyHt[sec] || EMPTY_H; }
function drawEmptySection(sec, y) {
  const c = EMPTY_COPY[sec], a = K.anim('empty:' + sec, 1, 7);
  faded(a, () => {
    K.card(SIDE, y, K.W - SIDE * 2, emptyH(sec), { r: 20, elev: 1 });
    emptyHt[sec] = 18 + K.empty(K.W / 2, y + 18 + 10 * (1 - a), c[0], c[1], c[2], { w: 270 }) + 16;   // even padding
  });
}

// ===== TASK ROW: round checkbox, strike-through, swipe-left to delete =====
function rowState(id) {
  if (!rowUI[id]) rowUI[id] = { spr: K.spring(0, { k: 340, d: 30 }), pid: null, grab: 0, open: false, leaving: false, fade: 0 };
  return rowUI[id];
}
function closeAllRows(exceptId) {
  for (const id in rowUI) {
    const st = rowUI[id];
    if (String(exceptId) !== id && st.open && !st.leaving) { st.open = false; st.spr.to(0); }
  }
}

function drawTaskRow(t, x, y, w, lift) {
  const st = rowState(t.id);
  if (!st.leaving) aboveUndo(() => { rowSwipe(t, st, x, y, w); rowTaps(t, st, x, y, w); });
  const off = st.spr.v;
  const born = bornAt[t.id] == null ? 1 : K.since(bornAt[t.id], 0, 450, 'outBack');
  const cx = x + w / 2, cy = y + ROW_H / 2;
  push();                                              // pop-in: new and restored rows grow from 90 %
  translate(cx, cy); scale(0.9 + 0.1 * born); translate(-cx, -cy);
  faded(K.clamp(born * 1.5, 0, 1) * (1 - st.fade), () => {
    if (off < -0.5) {                                  // swiping: the red action sits under the row, both clipped to its slot
      K.clip(x, y, w, ROW_H, () => { drawDeleteAction(x, y, w, -off); drawRowCard(t, x + off, y, w, 0); }, 16);
    } else drawRowCard(t, x + off, y, w, lift);
  });
  pop();
}

// Swipe-to-reveal. A row claims a finger that moves mostly sideways (K.scroll only claims vertical drags),
// follows it, and on release springs open (Delete showing), shut, or deletes after a long pull.
function rowSwipe(t, st, x, y, w) {
  let p = st.pid == null ? null : K.pointers.find(q => q.id === st.pid);
  if (!p && st.pid != null) {                          // the finger just lifted
    st.pid = null;
    if (st.spr.v < -w * 0.6) { deleteTask(t); return; }
    st.open = st.spr.v < -ACTION_W / 2;
    st.spr.to(st.open ? -ACTION_W : 0);
    K.sfx(st.open ? 'tick' : 'back');
    return;
  }
  if (!p) p = claimSideways(t, st, x, y, w);
  if (!p) return;
  let off = st.grab + (p.x - p.sx);
  if (off > 0) off *= 0.25;                            // rubber band: rows do not swipe right
  if (off < -ACTION_W) off = -ACTION_W + (off + ACTION_W) * 0.8;
  st.spr.set(off);                                     // set() while dragging; to() on release springs from here
}
// K.holdIn is clipped and deaf under a sheet, so only a finger that started on the visible row counts.
// KIT GAP (v1.1): no public "claim this finger" call; setting `claimed` stops it becoming a tap or a scroll.
function claimSideways(t, st, x, y, w) {
  const q = K.holdIn(x, y, w, ROW_H), dx = q ? q.x - q.sx : 0;
  if (!q || Math.abs(dx) <= 10 || Math.abs(dx) <= Math.abs(q.y - q.sy)) return null;
  q.claimed = 'row:' + t.id;
  st.pid = q.id; st.grab = st.spr.v;
  closeAllRows(t.id);
  return q;
}

// Custom hit areas: inside K.clip, K.tapIn only accepts taps that start on the visible part of the row, and
// mapVisible lists only that part for the tester.
function rowTaps(t, st, x, y, w) {
  if (st.open) {                                       // open row: Delete, or tap the row to close it
    mapVisible('delete:' + t.title, x + w - ACTION_W, y, ACTION_W, ROW_H);
    if (K.tapIn(x + w - ACTION_W, y, ACTION_W, ROW_H)) { deleteTask(t); return; }
    if (K.tapIn(x, y, w - ACTION_W, ROW_H)) { st.open = false; st.spr.to(0); K.sfx('back'); }
    return;
  }
  mapVisible('check:' + t.title, x, y, 56, ROW_H);    // the whole left strip is the checkbox: a 56 px target
  if (K.tapIn(x, y, 56, ROW_H)) { toggleDone(t, x + 30, y + ROW_H / 2); return; }
  mapVisible('edit:' + t.title, x + 56, y, w - 56, ROW_H);
  if (K.tapIn(x + 56, y, w - 56, ROW_H)) { K.sfx('tap'); openSheet('edit', t); }
}

function drawRowCard(t, x, y, w, lift) {
  const tick = K.springTo('chk:' + t.id, t.done ? 1 : 0, { k: 380, d: 17 });   // overshoots = the "pop"
  const strike = K.anim('strike:' + t.id, t.done ? 1 : 0, 9);
  const press = K.anim('press:' + t.id, K.holdIn(x, y, w, ROW_H) ? 1 : 0, 25);
  K.card(x, y, w, ROW_H, { r: 16, elev: lift > 0.3 ? 3 : 1 });
  if (press > 0.02) K.rect(x, y, w, ROW_H, { r: 16, fill: K.alpha(K.C.text, 0.05 * press) });
  const cx = x + 30, cy = y + ROW_H / 2;              // checkbox: grey ring -> accent disc -> white tick
  K.circle(cx, cy, 12, { fill: 'none', stroke: t.done ? ACCENT : K.alpha(K.C.text, 0.22), sw: 2 });
  if (tick > 0.02) {
