  const tw = K.text(t.title, tx, y + 29, 'body', K.mix(K.C.text, K.C.text3, strike), { weight: 500, maxW: w - 106 });
  if (strike > 0.01) K.line(tx - 2, y + 23, tx - 2 + (tw + 4) * strike, y + 23, K.alpha(K.C.text, 0.5), 1.5);
