// ===== TASK ACTIONS =====
function toggleDone(t, cx, cy) {
  const px = cx == null ? ui.ringPos.x : cx, py = cy == null ? ui.ringPos.y : cy;
  t.done = !t.done;
  t.doneAt = t.done ? Date.now() : 0;
  if (t.done) {
    settleAt[t.id] = K.t + 0.75;                       // strike draws on, then the row slides to Done
    K.sfx('success');
    K.ring(px, py, { color: ACCENT, r1: 34 });
    K.burst(px, py, { n: 12, colors: [ACCENT, SKY, '#ffd60a'], speed: 260, gravity: 0, size: 4, life: 450 });
    if (t.due <= todayNum() && todayStats().open === 0) celebrate();
  } else {
    delete settleAt[t.id];
    K.sfx('back');
    K.ring(px, py, { color: K.C.text3, r1: 26 });
  }
  persist();
}
// WIN state: the last task due today is done.
function celebrate() {
  K.sfx('win');
  K.burst(ui.ringPos.x, ui.ringPos.y, { n: 70, shape: 'confetti', colors: [ACCENT, SKY, '#ffd60a', '#ff375f', '#34c759'],
    speed: 520, gravity: 900, life: 1400, angle: -Math.PI / 2, spread: 2.2 });
  K.toast('All done for today', { tone: 'good', icon: 'trophy' });
}
function deleteTask(t) {
  const st = rowState(t.id);
  if (st.leaving) return;
  st.leaving = true; st.open = false; st.spr.to(-K.W);
  K.sfx('whoosh');
  K.tween(st, { fade: 1 }, 260, { ease: 'inCubic', onDone: () => removeTask(t) });
}
function removeTask(t) {
  const index = tasks.indexOf(t);
  if (index < 0) return;
  tasks.splice(index, 1);
  ui.undo = { task: t, index, until: K.t + UNDO_S };
  persist();
}
function restoreTask() {
  const u = ui.undo;
  if (!u) return;
  tasks.splice(Math.min(u.index, tasks.length), 0, u.task);
  const st = rowState(u.task.id);
  st.leaving = false; st.fade = 0; st.open = false; st.spr.set(0);
  bornAt[u.task.id] = K.t;
  ui.undo.until = 0;
  persist(); K.sfx('pop');
  K.toast('Task restored', { tone: 'good', icon: 'refresh' });
}

// ===== UNDO BAR (after a delete) =====
function drawUndoBar() {
  const u = ui.undo, live = !!u && K.t < u.until;
  const k = K.springTo('undo', live ? 1 : 0, { k: 260, d: 24 });
  if (!u) return;
  if (!live && k < 0.02) { ui.undo = null; return; }
  const x = SIDE, w = K.W - SIDE * 2, h = 52;
  const y = viewBottom() - 12 - h + (1 - k) * (h + 30);
  K.rect(x, y, w, h, { r: 16, fill: '#1d2029', elev: 3 });
  K.icon('trash', x + 26, y + h / 2, 18, 'rgba(255,255,255,0.72)');
  K.text('Deleted “' + u.task.title + '”', x + 48, y + h / 2 + 0.5, 'subhead', '#ffffff',
    { base: 'middle', weight: 600, maxW: w - 140 });
  K.rect(x + 16, y + h - 5, (w - 32) * K.clamp((u.until - K.t) / UNDO_S, 0, 1), 2, { r: 1, fill: 'rgba(255,255,255,0.28)' });
  if (live && K.button('undo', x + w - 84, y + 8, 76, 36, 'Undo', { style: 'ghost', color: '#8fb4ff', role: 'headline' })) restoreTask();
