// ===== ADD / EDIT SHEET =====
function openSheet(mode, t) {
  closeAllRows();
  const s = ui.sheet;
  s.mode = mode; s.editId = t ? t.id : null; s.error = false; s.errorAt = -9;
  s.draft = t ? { title: t.title, due: t.due, prio: t.prio } : { title: '', due: todayNum(), prio: 0 };
