}
function drawTaskSheet() {
  const s = ui.sheet, wasOpen = s.open;
  // Buttons inside close it with close(); a drag down or a backdrop tap closes it too. The return value is the new state.
  s.open = K.sheet('task', s.open, SHEET_H + K.safe.bottom, (x, y, w, h, close) => drawSheetBody(s, y, w, close));
  if (wasOpen && !s.open) K.blurInputs();             // however it closed, the keyboard goes with it
}

function drawSheetBody(s, y, w, close) {
  const d = s.draft, L = 24, fw = w - L * 2;
  if (!d) return;
  const save = () => { if (submitSheet()) close(); };
  K.text(s.mode === 'add' ? 'New Task' : 'Edit Task', L, y + 50, 'title2', K.C.text);
  if (K.iconButton('sheetClose', w - 38, y + 42, 30, 'close', { style: 'tinted', color: K.C.text2 })) close();
  if (s.error && (d.title || '').trim()) s.error = false;   // ERROR state: stays red until the task has a name
  const wig = errorWiggle(s.errorAt);                  // ...and the field shakes once when it appears
  d.title = K.input('taskTitle', L + wig, y + 68, fw, 52, d.title, { placeholder: 'What needs doing?', onEnter: save });
  if (s.error) {
    K.rect(L + wig, y + 68, fw, 52, { r: 12, fill: 'none', stroke: K.C.bad, sw: 2 });
    K.text('Give the task a name first', L + 4, y + 138, 'footnote', K.C.bad);
  }
  if (s.mode === 'add') drawSuggestions(d, L, y + 160, fw);
  else drawEditActions(s, L, y + 160, fw, close);
