  const di = K.segmented('due', L, y + 246, fw, DUE_CHOICES.map(c => c.label), dueIndex(d.due));
  if (di !== dueIndex(d.due)) d.due = todayNum() + DUE_CHOICES[di].days;
  K.text('PRIORITY', L, y + 312, 'label', K.C.text2);
  let px = L;
  PRIO_NAMES.forEach((name, i) => {
    const r = choicePill('priority:' + name, px, y + 322, name, d.prio === i, prioColor(i));
    if (r.tap && d.prio !== i) { d.prio = i; K.sfx('select'); K.ring(px + r.w / 2, y + 339, { color: prioColor(i), r1: 36 }); }
    px += r.w + 8;
  });
  const label = s.mode === 'add' ? 'Add Task' : 'Save Changes';
  if (K.button('sheetSave', L, y + 380, fw, 52, label, { icon: s.mode === 'add' ? 'plus' : 'check' })) save();
}

function drawSuggestions(d, x, y, w) {
  K.text('SUGGESTIONS', x, y, 'label', K.C.text2);
  let px = x;
  for (const s of SUGGESTIONS) {
    if (px + pillWidth(s) > x + w) break;             // only as many as fit on one line
    const r = choicePill('suggest:' + s, px, y + 10, s, d.title === s, ACCENT);
    if (r.tap) { d.title = s; K.sfx('select'); K.ring(px + r.w / 2, y + 27, { color: ACCENT, r1: 44 }); }
