}

// Saves the form; returns false (and shows the error state) when the task has no name.
function submitSheet() {
  const s = ui.sheet, d = s.draft, title = (d.title || '').trim();
  if (!title) { s.error = true; s.errorAt = K.t; K.sfx('error'); return false; }
  if (s.mode === 'add') {
    const t = { id: nextId++, title, list: 'Inbox', due: d.due, prio: d.prio, done: false, doneAt: 0 };
    tasks.push(t); bornAt[t.id] = K.t;
    K.scrollTo('tasks', 0);
    K.toast('Added to ' + (d.due <= todayNum() ? 'Today' : 'Upcoming'), { tone: 'good', icon: 'check' });
  } else {
    const t = tasks.find(q => q.id === s.editId);
    if (t) { t.title = title; t.due = d.due; t.prio = d.prio; bornAt[t.id] = K.t; }
    K.toast('Changes saved', { tone: 'good' });
  }
  K.sfx('success'); persist();
  return true;
}
// A decaying side-to-side shake (the "wrong password" nudge) for invalid input.
function errorWiggle(at) { const t = K.t - at; return t < 0.5 ? Math.sin(t * 50) * 10 * (1 - t / 0.5) : 0; }

// ===== HABITS SCREEN =====
function isHabitDone(h) { return h.count >= h.goal; }
// On the first open of a new day: yesterday's result joins the week, the streak grows or breaks.
function rolloverHabits() {
  const today = todayNum();
  for (const h of habits) {
    const gap = today - h.day;
    if (gap <= 0) continue;
    const kept = isHabitDone(h);
    h.streak = kept && gap === 1 ? h.streak + 1 : 0;
    h.week.push(kept ? 1 : 0);
    for (let i = 1; i < Math.min(gap, 7); i++) h.week.push(0);       // days the app was not opened count as missed
    h.week = h.week.slice(-6);
    h.count = 0; h.day = today;
  }
}
function dayRatio(ago) {
  if (!habits.length) return 0;
  if (ago === 0) return habits.reduce((n, h) => n + Math.min(1, h.count / h.goal), 0) / habits.length;
  return habits.reduce((n, h) => n + (h.week[6 - ago] || 0), 0) / habits.length;
}

function drawHabits() {
  screenBackdrop();
  const doneN = habits.filter(isHabitDone).length;
  const sub = doneN === habits.length ? 'Perfect day. Every habit kept.' : 'Small steps, every day', top = K.navBar.top(sub);
  const listY = WEEK_H + 8 + HEAD_H, chartY = listY + habits.length * (HABIT_H + HABIT_GAP) + 6;
  const off = K.scroll('habits', 0, 0, K.W, viewBottom(), top + chartY + CHART_H + 24);
  const y0 = top - off;
  contentClip(() => {
    const e = i => K.stagger(i, 45, 420);             // v1.1: times from THIS screen's opening (no blink while it fades out)
    faded(e(0), () => drawWeekStrip(SIDE, y0 + rise(e(0)), K.W - SIDE * 2));
    sectionHeader('TODAY', doneN + ' of ' + habits.length, y0 + WEEK_H + 8 + rise(e(1)), e(1));
    habits.forEach((h, i) => drawHabitCard(h, SIDE, y0 + listY + i * (HABIT_H + HABIT_GAP), K.W - SIDE * 2, e(i + 2)));
    const eLast = e(habits.length + 2);
    faded(eLast, () => drawWeekChart(SIDE, y0 + chartY + rise(eLast), K.W - SIDE * 2));
  });
  K.navBar(TITLE_HABITS, off, { sub });
}

function drawWeekStrip(x, y, w) {
  K.card(x, y, w, WEEK_H, { r: 20 });
  const cw = (w - 12) / 7;
  for (let i = 0; i < 7; i++) {
    const ago = 6 - i, ts = Date.now() - ago * DAY_MS, cx = x + 6 + cw * i + cw / 2, isToday = ago === 0;
    if (isToday) K.rect(cx - cw / 2 + 2, y + 8, cw - 4, WEEK_H - 16, { r: 14, fill: K.alpha(ACCENT, 0.09) });
    K.text(K.fmt.date(ts, { weekday: 'narrow' }), cx, y + 30, 'caption', isToday ? ACCENT : K.C.text3, { align: 'center', weight: 700 });
    const t = K.anim('wk:' + i, dayRatio(ago), 6) * K.stagger(i, 60, 700);   // rings sweep in one after another
    K.progressRing(cx, y + 60, 15, t, { width: 4, color: isToday ? [ACCENT, SKY] : K.alpha(ACCENT, 0.7), glow: 0 });
    K.text(String(new Date(ts).getDate()), cx, y + 64.5, 'caption', isToday ? K.C.text : K.C.text2, { align: 'center', weight: 600 });
  }
}

function drawHabitCard(h, x, y, w, e) {
  y += rise(e);
  aboveUndo(() => habitInput(h, x, y, w));
  const done = isHabitDone(h), streak = h.streak + (done ? 1 : 0);
  faded(e, () => {
    K.card(x, y, w, HABIT_H, { r: 18, elev: 1 });
    K.rect(x + 14, y + HABIT_H / 2 - 22, 44, 44, { r: 13, fill: K.alpha(h.color, 0.14) });
    K.icon(h.icon, x + 36, y + HABIT_H / 2, 22, h.color, { weight: 2.2 });
    K.text(h.name, x + 72, y + 33, 'headline', K.C.text, { maxW: w - 150 });
    const shown = Math.round(K.count('streak:' + h.id, streak, 500));
    let sub = streak ? shown + '-day streak' : 'Start a streak today';
    if (h.goal > 1) sub = h.count + ' of ' + h.goal + ' ' + h.unit + '  ·  ' + sub;
    K.icon('flame', x + 79, y + 50, 14, streak ? K.C.warn : K.C.text3, { weight: 2.2 });
    K.text(sub, x + 91, y + 55, 'footnote', K.C.text2, { maxW: w - 160 });
    drawHabitButton(h, x + w - 38, y + HABIT_H / 2, done);
  });
}
// Counter habits show a ring that fills per tap; once met (or for yes/no habits) a disc springs in with a tick.
function drawHabitButton(h, cx, cy, done) {
  const k = K.springTo('hb:' + h.id, done ? 1 : 0, { k: 360, d: 16 });
  if (h.goal > 1 && !done) {
    K.progressRing(cx, cy, 18, K.anim('hp:' + h.id, h.count / h.goal, 10), { width: 5, color: h.color, glow: 0 });
    K.icon('plus', cx, cy, 18, h.color, { weight: 2.6 });
    return;
  }
  K.circle(cx, cy, 20, { fill: 'none', stroke: K.alpha(h.color, 0.35), sw: 2.5 });
  if (k > 0.02) {
    K.circle(cx, cy, 20 * k, { fill: h.color, elev: 1 });
    K.icon('check', cx, cy, 20 * Math.min(k, 1.15), '#ffffff', { weight: 3 });
  }
}

// The whole card is one custom hit area (clipped by contentClip + aboveUndo; mapVisible for the tester): tap logs, hold resets.
function habitInput(h, x, y, w) {
  mapVisible('habit:' + h.name, x, y, w, HABIT_H);
  // KIT GAP (v1.1): K.longPress ignores K.clip, so a hold only counts for a finger K.holdIn (clipped) also sees.
  if (K.holdIn(x, y, w, HABIT_H) && K.longPress(x, y, w, HABIT_H)) { resetHabit(h); return; }
  if (K.tapIn(x, y, w, HABIT_H)) logHabit(h, x + w - 38, y + HABIT_H / 2);
}
function logHabit(h, bx, by) {
  if (isHabitDone(h) && h.goal === 1) {                // yes/no habit: a second tap undoes today
    h.count = 0; persist(); K.sfx('back'); K.ring(bx, by, { color: K.C.text3, r1: 30 });
    return;
  }
  if (isHabitDone(h)) { K.sfx('tick'); K.toast('Goal met. Hold the card to reset', { icon: 'check', tone: 'good' }); return; }
  h.count += 1; persist();
  K.ring(bx, by, { color: h.color, r1: 38 });
  if (!isHabitDone(h)) { K.sfx('pop', { pitch: 0.8 + 0.06 * h.count }); return; }   // each tap a little higher
  K.sfx('success');
  K.burst(bx, by, { n: 18, colors: [h.color, '#ffd60a', SKY], shape: 'star', speed: 280, gravity: 200, size: 6, life: 700 });
  if (habits.every(isHabitDone)) {                     // WIN state for the habits screen
    K.sfx('win');
    K.burst(K.W / 2, K.navBar.top(true), { n: 70, shape: 'confetti', colors: [ACCENT, SKY, '#ffd60a', '#ff375f'], speed: 520, gravity: 900, life: 1400 });
    K.toast('Perfect day! ' + habits.length + ' for ' + habits.length, { tone: 'good', icon: 'trophy' });
  }
}
function resetHabit(h) {
  h.count = 0; persist(); K.sfx('back');
  K.toast('Reset “' + h.name + '” for today', { icon: 'refresh' });
}

function drawWeekChart(x, y, w) {
  K.card(x, y, w, CHART_H, { r: 20 });
  const vals = [], labels = [];
  for (let ago = 6; ago >= 0; ago--) {
    vals.push(ago === 0 ? habits.filter(isHabitDone).length : habits.reduce((n, h) => n + (h.week[6 - ago] || 0), 0));
    labels.push(K.fmt.date(Date.now() - ago * DAY_MS, { weekday: 'narrow' }));
  }
  const kept = vals.reduce((a, b) => a + b, 0), pct = Math.round(100 * kept / Math.max(1, 7 * habits.length));
  const best = habits.reduce((m, h) => Math.max(m, h.streak + (isHabitDone(h) ? 1 : 0)), 0);
  K.text('THIS WEEK', x + 16, y + 30, 'label', K.C.text3);
  K.text(pct + '% of habits kept', x + 16, y + 58, 'title3', K.C.text);
  const chipLabel = best + '-day best';
  K.chip(x + w - 16 - K.chipWidth(chipLabel, { icon: 'flame' }), y + 16, chipLabel, { color: K.C.warn, icon: 'flame' });
  K.bars(vals, x + 16, y + 76, w - 32, 76, { labels, highlight: 6, color: ACCENT, max: Math.max(1, habits.length) });
}

