    K.text('Tasks 1.0  ·  Your lists stay on this phone', K.W / 2, y + 30, 'footnote', K.C.text3, { align: 'center', alpha: e(4) });
  });
  K.navBar('Settings', off, { sub });
}

function drawProfileCard(x, y, w) {
  K.card(x, y, w, 80, { r: 20 });
  K.avatar(x + 44, y + 40, 26, PROFILE.name);
  K.text(PROFILE.name, x + 84, y + 36, 'headline', K.C.text);
  const openN = tasks.filter(t => !t.done).length;
  K.text(openN + ' open tasks  ·  ' + habits.length + ' habits', x + 84, y + 57, 'footnote', K.C.text2);
  K.chip(x + w - 16 - K.chipWidth(PROFILE.plan), y + 28, PROFILE.plan, { color: ACCENT });
}

// A 52 px settings row that follows liveInBand (the kit lists it at its full rect).
function bandRow(id, x, y, w, opts) { return liveInBand(y, 52, () => K.listRow(id, x, y, w, 52, opts)); }

function drawGeneralGroup(y, a) {
  sectionHeader('GENERAL', '', y, a);
  const x = SIDE, w = K.W - SIDE * 2, top = y + HEAD_H;
  K.card(x, top, w, 52 * 4, { r: 16, elev: 1, alpha: a });
  for (let i = 1; i < 4; i++) K.line(x + 58, top + 52 * i, x + w, top + 52 * i, K.C.line, 1, { alpha: a });
  const soundOpts = { title: 'Sounds', icon: 'sound', iconColor: '#ff9f0a', toggle: prefs.sound, alpha: a };
  const snd = bandRow('setSound', x, top, w, soundOpts).toggle;
  if (snd !== prefs.sound) { prefs.sound = snd; K.sound = snd; persist(); }
  const remindOpts = { title: 'Daily reminder', icon: 'bell', iconColor: '#ff3b30', toggle: prefs.reminder, alpha: a };
  const rem = bandRow('setRemind', x, top + 52, w, remindOpts).toggle;
  if (rem !== prefs.reminder) {
    prefs.reminder = rem; persist();
    K.toast(rem ? 'Reminder on at ' + REMIND_TIMES[prefs.remindAt] : 'Reminder off', { icon: 'bell' });
  }
  // Disabled look while the reminder is off: faded through { alpha } and deaf through K.inert (K.listRow has no { disabled }).
  const timeOpts = { title: 'Reminder time', icon: 'clock', iconColor: '#5856d6', value: REMIND_TIMES[prefs.remindAt], chevron: true,
    alpha: a * K.anim('remindOn', prefs.reminder ? 1 : 0.4, 10) };
  K.inert(!prefs.reminder, () => {
    if (bandRow('setTime', x, top + 104, w, timeOpts).tap) {
      prefs.remindAt = (prefs.remindAt + 1) % REMIND_TIMES.length; persist();
      K.toast('Reminder moved to ' + REMIND_TIMES[prefs.remindAt], { icon: 'clock' });
    }
  });
  const showOpts = { title: 'Show completed', icon: 'check', iconColor: '#34c759', toggle: prefs.showDone, alpha: a };
  const show = bandRow('setShowDone', x, top + 156, w, showOpts).toggle;
  if (show !== prefs.showDone) { prefs.showDone = show; persist(); }
  return top + 52 * 4 + 8;
}

function drawOrderGroup(y, a) {
  sectionHeader('LIST ORDER', '', y, a);
  const x = SIDE, w = K.W - SIDE * 2, top = y + HEAD_H;
  K.card(x, top, w, 62, { r: 16, elev: 1, alpha: a });
  const i = liveInBand(top + 14, 34, () => K.segmented('sort', x + 14, top + 14, w - 28, ['Due date', 'Priority'], prefs.sort, { alpha: a }));
  if (i !== prefs.sort) { prefs.sort = i; persist(); K.toast(i ? 'Sorted by priority' : 'Sorted by due date', { icon: 'filter' }); }
  return top + 62 + 8;
}

function drawDataGroup(y, a) {
  sectionHeader('DATA', '', y, a);
  const x = SIDE, w = K.W - SIDE * 2, top = y + HEAD_H;
  const doneCount = tasks.filter(t => t.done).length;
  K.card(x, top, w, 112, { r: 16, elev: 1, alpha: a });
  K.line(x + 16, top + 52, x + w - 16, top + 52, K.C.line, 1, { alpha: a });
  const clearOpts = { title: 'Clear completed', icon: 'trash', iconColor: '#8e8e93', value: String(doneCount), alpha: a };
  if (bandRow('clearDone', x, top, w, clearOpts).tap) clearCompleted(doneCount);
  const armed = K.t < ui.resetArmedUntil;              // inline confirm: the first tap arms, the second erases
  const label = armed ? 'Tap again to erase everything' : 'Reset sample data';
  const resetStyle = { style: armed ? 'danger' : 'tinted', color: K.C.bad, icon: armed ? 'alert' : 'refresh', alpha: a };
  if (liveInBand(top + 62, 38, () => K.button('reset', x + 16, top + 62, w - 32, 38, label, resetStyle))) {
    if (armed) resetAll(); else ui.resetArmedUntil = K.t + 3;
  }
  return top + 112 + 8;
}
